// Notifier wraps Wails native notifications with a platform fallback.
type Notifier struct {
	mu       sync.Mutex
	svc      *notifications.NotificationService
	ready    bool
	initErr  error
	lastErr  error
	logger   *log.Logger
	logFile  io.Closer
