package notify

import "strings"

func windowsToastXML(title, body, iconSrc string) string {
	var b strings.Builder
	b.WriteString(`<toast><visual><binding template="ToastGeneric">`)
	if iconSrc != "" {
		b.WriteString(`<image placement="appLogoOverride" src="`)
		b.WriteString(xmlEscape(iconSrc))
		b.WriteString(`"/>`)
	}
	b.WriteString(`<text>`)
	b.WriteString(xmlEscape(title))
	b.WriteString(`</text><text>`)
	b.WriteString(xmlEscape(body))
	b.WriteString(`</text></binding></visual><audio src="ms-winsoundevent:Notification.Default"/></toast>`)
	return b.String()
}

func xmlEscape(s string) string {
	return strings.NewReplacer(
		`&`, "&amp;",
		`<`, "&lt;",
		`>`, "&gt;",
		`"`, "&quot;",
		`'`, "&apos;",
	).Replace(s)
}

package notify

import (
	"strings"
	"testing"
)

func TestWindowsToastXMLIncludesIcon(t *testing.T) {
	xml := windowsToastXML(`A & B`, `body`, `file:///C:/icon.png`)
	if !strings.Contains(xml, `placement="appLogoOverride"`) {
		t.Fatalf("missing logo: %s", xml)
	}
	if !strings.Contains(xml, `src="file:///C:/icon.png"`) {
		t.Fatalf("missing src: %s", xml)
	}
	if !strings.Contains(xml, `A &amp; B`) {
		t.Fatalf("title not escaped: %s", xml)
	}
}

func TestWindowsToastXMLOmitsEmptyIcon(t *testing.T) {
	xml := windowsToastXML("title", "body", "")
	if strings.Contains(xml, "<image") {
		t.Fatalf("unexpected image: %s", xml)
	}
}

